<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const id=ref(''),data=ref<any>(),error=ref(''),loading=ref(false);async function load(){loading.value=true;try{data.value=await api(`/edge-gateways/${id.value}/health`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Edge gateway health</h2><p>Outbound-only uplink and Browse/Read/Subscribe-only site access.</p></div><div class="inline"><input v-model="id" placeholder="gateway_id"><button @click="load">Inspect</button></div></div><AsyncState :loading="loading" :error="error" :empty="!data"><pre>{{data}}</pre></AsyncState></section></template>
